{"name": "haversine", "code": "import math
def solve(inputs: dict) -> float:
    R=inputs.get('R',6371.0)
    lat1=math.radians(inputs['LAT1']);lon1=math.radians(inputs['LON1'])
    lat2=math.radians(inputs['LAT2']);lon2=math.radians(inputs['LON2'])
    dlat=lat2-lat1;dlon=lon2-lon1
    a=math.sin(dlat/2)**2+math.cos(lat1)*math.cos(lat2)*math.sin(dlon/2)**2
    return R*2*math.asin(math.sqrt(a))
"}
